1:
if [ -f "/var/lib/actions/actions-runner-secret" ]; then
  echo "Runner already registered." ;
else
  forgejo forgejo-cli actions generate-secret > /var/lib/actions/actions-runner-secret ;
  forgejo forgejo-cli actions register --name "actions-runner" --secret-file /var/lib/actions/actions-runner-secret > /var/lib/actions/actions-runner-uuid ;
  echo "Runner Registered!";
fi;
cp /var/lib/actions/config.tmpl.yaml /var/lib/actions/config.yaml ; sed -i "s/<RUNNER_TOKEN>/$(cat /var/lib/actions/actions-runner-secret)/" /var/lib/actions/config.yaml ; sed -i "s/<RUNNER_UUID>/$(cat /var/lib/actions/actions-runner-uuid)/" /var/lib/actions/config.yaml ;
